+import type OpenAI from 'openai';
+
+/** OpenAI stops accepting new self-serve fine-tuning jobs on this date. */
+export const FINE_TUNING_CUTOFF = new Date('2027-01-06T00:00:00Z');
+
+/**
+ * Replacement for the retired gpt-3.5-turbo (shut down 2026-10-23), taken from the
+ * deprecations table. UNVERIFIED as a fine-tuning base: its model page lists inference only.
+ */
+export const FINE_TUNING_BASE_MODEL = 'gpt-5.6-terra';
+
+export class FineTuningUnavailableError extends Error {
+  constructor(message?: string) {
+    super(
+      message ??
+        'OpenAI no longer accepts new self-serve fine-tuning jobs (ended 2027-01-06). ' +
+          'Use prompt-based customization with a current model, or contact OpenAI about non-self-serve access.',
+    );
+    this.name = 'FineTuningUnavailableError';
+  }
+}
+
+export async function createFineTuningJob(
+  client: OpenAI,
+  params: OpenAI.FineTuning.JobCreateParams,
+  now: Date = new Date(),
+) {
+  if (now.getTime() >= FINE_TUNING_CUTOFF.getTime()) {
+    throw new FineTuningUnavailableError();
+  }
+  return client.fineTuning.jobs.create(params);
+}
