diff --git a/test/createJob.test.ts b/test/createJob.test.ts
new file mode 100644
index 0000000..a7b2c37
--- /dev/null
+++ b/test/createJob.test.ts
@@ -0,0 +1,21 @@
+import * as assert from 'assert';
+import * as fs from 'fs';
+import { createFineTuningJob, FineTuningUnavailableError, FINE_TUNING_BASE_MODEL } from '../src/createJob';
+
+(async () => {
+  let calls = 0;
+  let body: any;
+  const client: any = { fineTuning: { jobs: { create: async (p: any) => (calls++, (body = p), { id: 'ftjob-1' }) } } };
+  const r = await createFineTuningJob(client, { model: FINE_TUNING_BASE_MODEL, training_file: 'f' }, new Date('2026-12-01T00:00:00Z'));
+  assert.strictEqual(r.id, 'ftjob-1');
+  assert.strictEqual(body.model, 'gpt-5.6-terra');
+  await assert.rejects(
+    createFineTuningJob(client, { model: FINE_TUNING_BASE_MODEL, training_file: 'f' }, new Date('2027-01-06T00:00:00Z')),
+    FineTuningUnavailableError,
+  );
+  assert.strictEqual(calls, 1);
+  const src = fs.readFileSync(__dirname + '/../src/index.ts', 'utf8');
+  assert.ok(!src.includes('gpt-3.5-turbo'));
+  assert.ok(!src.includes('client.fineTuning.jobs.create'));
+  console.log('ok');
+})();
